"""Socket identity/account generation ownership without live device access."""
from test_session_lifecycle import run_session_cases


def test_realtime_socket_and_timer_ownership(tmp_path):
    run_session_cases(tmp_path, REALTIME_CASES, "realtime-response-ownership")


REALTIME_CASES = r'''
function opened(f){f.call('startRealtime()');const socket=f.sockets.at(-1);socket.readyState=1;socket.onopen();return socket}
for(const language of ['en','zh-CN']){
 lifecycleTest(language+': current socket preserves heartbeat, event and reconnect behavior',async()=>{const f=fixture(language),socket=opened(f);assert.equal(f.intervals.size,2);f.call('startRealtime()');assert.equal(f.sockets.length,1);for(const t of f.intervals.values())if(t.delay===20000)t.callback();assert.deepEqual(socket.sent,[JSON.stringify({type:'heartbeat'})]);socket.onmessage({data:JSON.stringify({type:'node.upsert',node:{node_id:'CURRENT',authorized:true,online:true}})});assert.equal(f.call('state.nodes[0].node_id'),'CURRENT');socket.readyState=3;socket.onclose();assert.equal(f.intervals.size,0);const timer=[...f.timeouts.values()].find(x=>x.delay>=1000&&x.delay<1350);assert.ok(timer);timer.callback();assert.equal(f.sockets.length,2);const replacement=f.sockets[1];replacement.readyState=1;replacement.onopen();assert.equal(f.requests.length,3);reply(f,0,'RECOVERED');await settle();assert.equal(f.call('state.nodes[0].node_id'),'RECOVERED')});
 for(const type of ['open','message','close'])lifecycleTest(language+': retired socket callback cannot affect replacement '+type,()=>{const f=fixture(language),old=opened(f),callbacks=socketCallbacks(old);account(f);const fresh=opened(f),timers=[...f.intervals.keys()];const ack=f.call('eventLastAck');f.advance(100);callbacks[type](type==='message'?{data:JSON.stringify({type:'node.upsert',node:{node_id:'OLD',authorized:true}})}:undefined);assert.equal(f.call('state.nodes.length'),0);assert.equal(f.call('eventSocket'),fresh);assert.equal(f.call('eventLastAck'),ack);assert.deepEqual([...f.intervals.keys()],timers);assert.equal(f.requests.length,0)});
 lifecycleTest(language+': queued old heartbeat and watchdog do nothing after account replacement',()=>{const f=fixture(language),old=opened(f),timers=[...f.intervals.values()];account(f);const fresh=opened(f);old.readyState=1;f.advance(60000);const closed=old.closed.length;timers.forEach(t=>t.callback());assert.equal(old.sent.length,0);assert.equal(old.closed.length,closed);assert.equal(fresh.closed.length,0)});
 lifecycleTest(language+': canceled reconnect cannot create or replace another account socket',()=>{const f=fixture(language),old=opened(f);old.readyState=3;old.onclose();const pending=[...f.timeouts.values()].find(x=>x.delay>=1000&&x.delay<1350).callback;account(f);const fresh=opened(f);pending();assert.equal(f.sockets.length,2);assert.equal(f.call('eventSocket'),fresh)});
 lifecycleTest(language+': changed user object replaces the old socket even without showAuth',()=>{const f=fixture(language),old=opened(f),callbacks=socketCallbacks(old);f.call("state.user={id:'user-b',email:'b@example.test',role:'user'};startRealtime()");assert.equal(f.sockets.length,2);assert.equal(old.closed.length,1);callbacks.message({data:JSON.stringify({type:'node.upsert',node:{node_id:'OLD'}})});assert.equal(f.call('state.nodes.length'),0)});
 lifecycleTest(language+': same-user new login generation invalidates queued callbacks',()=>{const f=fixture(language),old=opened(f),callbacks=socketCallbacks(old);f.call('resetLoginVerification();startRealtime()');assert.equal(f.sockets.length,2);callbacks.message({data:JSON.stringify({type:'node.upsert',node:{node_id:'OLD'}})});assert.equal(f.call('state.nodes.length'),0)});
 lifecycleTest(language+': current node removal refresh uses socket ownership through completion',async()=>{const f=fixture(language),old=opened(f);old.onmessage({data:JSON.stringify({type:'node.remove'})});assert.equal(f.requests.length,3);old.readyState=3;old.onclose();reply(f,0,'OLD');await settle();assert.equal(f.call('state.nodes.length'),0)});
 lifecycleTest(language+': current malformed events and watchdog retain existing handling',()=>{const f=fixture(language),socket=opened(f);socket.onmessage({data:'{'});assert.equal(f.call('state.nodes.length'),0);f.advance(56000);[...f.intervals.values()].find(t=>t.delay===10000).callback();assert.deepEqual(socket.closed,[[4000,'heartbeat timeout']])});
 lifecycleTest(language+': signed-out state does not open or reconnect sockets',()=>{const f=fixture(language);f.call('showAuth();startRealtime();scheduleRealtimeReconnect()');assert.equal(f.sockets.length,0);assert.equal(f.intervals.size,0);assert.equal(f.timeouts.size,0)});
}
'''
